#include <vector>
#include <unordered_map>
#include <algorithm>

int longest_sum_k(std::vector<int> nums, int k) {
    std::unordered_map<long long, int> first;
    first[0] = -1;
    long long total = 0;
    int best = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
        total += nums[i];
        auto it = first.find(total - k);
        if (it != first.end()) best = std::max(best, i - it->second);
        if (!first.count(total)) first[total] = i;
    }
    return best;
}
